"""Read only the small JSON/text evidence generated by this project."""
import json
from pathlib import Path
root=Path('/root/gpufree-data/semantic/scripts/260920SensorVisualizer/v06/single0602Headless')
names=('isaac_acceptance.json','mcap_validation.json','gui_input.json','gui_shutdown.json',
       'gui_exit_cleanup.json','capture_lifecycle.json','linux_tests.json','linux_tests.txt','lifecycle_mcap_validation.json')
out={}
for name in names:
    path=root/'reports'/name
    if path.is_file():
        if path.stat().st_size>65536:raise ValueError('Evidence size unexpectedly large: '+name)
        out[name]=json.loads(path.read_text()) if path.suffix=='.json' else path.read_text()
for path in (root/'reports/history').glob('capture_lifecycle_*.json'):
    out['history/'+path.name]=json.loads(path.read_text())
print(json.dumps(out,ensure_ascii=False))
